//! Ramp fixtures generated by the pinned original renderer.
use filmcraft_project::{Param,ParamValue};
use filmcraft_render::{effects::{apply,FxCtx},image::Image};
use serde_json::json;
fn main(){
 let mut cases=vec![];
 for(w,h)in [(1,7),(7,1),(6,4),(18,10)]{for shape in [0,1]{for blend in [0.0,25.0,100.0]{for(start,end)in [([None,Some(0.0)],[None,None]),([Some(0.0),Some(0.0)],[Some(0.0),Some(0.0)]),([Some(-1.25),None],[None,Some(2.125)]),([Some(1.23456789012345),Some(2.0)],[Some(20.0),Some(-3.0)])]{for alternate in [false,true]{
  let rgba:Vec<u8>=(0..w*h).flat_map(|i|[[64,128,192,128],[0,0,0,0],[0,255,0,255],[255,0,0,64],[128,64,255,1]][(i+i/w)%5]).collect();
  let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;[filmcraft_color::srgb_to_linear(p[0]as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[1]as f32/255.0)*a,filmcraft_color::srgb_to_linear(p[2]as f32/255.0)*a,a]}).collect();
  let(mut image,mut effect)=(Image{w,h,px},filmcraft_project::effect_defs().iter().find(|e|e.id=="ramp").unwrap().instance());
  for(name,point)in [("start",start),("end",end)] {effect.params.insert(name.into(),Param::new(ParamValue::Vec2(filmcraft_geom::Vec2::new(point[0].unwrap_or(f64::NAN),point[1].unwrap_or(f64::NAN)))));}
  let(sc,ec)=if alternate {([-1.0,2.0,0.5,0.0],[0.75,0.25,-1.0,2.0])}else{([0.0,0.0,0.0,1.0],[1.0;4])};
  effect.params.insert("start_color".into(),Param::new(ParamValue::Color(sc)));effect.params.insert("end_color".into(),Param::new(ParamValue::Color(ec)));
  effect.params.insert("shape".into(),Param::new(ParamValue::Choice(shape)));effect.params.insert("blend".into(),Param::new(ParamValue::Float(blend)));
  let cx=FxCtx{t:filmcraft_time::Tick(0),px_scale:1.0,seconds:0.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};apply(&mut image,&effect,&cx);
  cases.push(json!({"parameters":{"start":start,"end":end,"startColor":sc,"endColor":ec,"shape":if shape==0 {"linear"}else{"radial"},"blend":blend},"width":w,"height":h,"rgba":rgba,"bits":image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>()}));
 }}}}}
 let mut media=vec![];
 for shape in [0u32,1] {for tick in [0u64,250000,500000] {
  let rgba:Vec<u8>=(0..256).flat_map(|i|{let v=if i%16<8&&i/16<12 {255}else{32};[v,v,v,if i%16<8&&i/16<12 {128}else{0}]}).collect();
  let mut frames=vec![];
  for index in 0..(1000000-tick).div_ceil(100000) {
   let local=(tick+index*100000).min(500000);let progress=local as f64/500000.0;
   let px:Vec<f32>=rgba.chunks_exact(4).flat_map(|p|{let a=p[3] as f32/255.0;let v=filmcraft_color::srgb_to_linear(p[0] as f32/255.0)*a;[v,v,v,a]}).collect();
   let mut image=Image{w:16,h:16,px};
   let mut effect=filmcraft_project::effect_defs().iter().find(|e|e.id=="ramp").unwrap().instance();
   for(name,a,b)in [("start",[-1.25,0.0],[4.0,8.0]),("end",[9.0,2.0],[3.0,10.0])] {
    let p=filmcraft_geom::Vec2::new(a[0]+(b[0]-a[0])*progress,a[1]+(b[1]-a[1])*progress);
    effect.params.insert(name.into(),Param::new(ParamValue::Vec2(p)));
   }
   for(name,a,b)in [("start_color",[-1.0,2.0,0.5,0.0],[1.0,0.0,0.0,1.0]),("end_color",[0.75,0.25,-1.0,2.0],[0.0,1.0,1.0,0.0])] {
    let color=std::array::from_fn(|i|(a[i]+(b[i]-a[i])*progress)as f32);
    effect.params.insert(name.into(),Param::new(ParamValue::Color(color)));
   }
   effect.params.insert("shape".into(),Param::new(ParamValue::Choice(shape)));
   effect.params.insert("blend".into(),Param::new(ParamValue::Float(progress*100.0)));
   let cx=FxCtx{t:filmcraft_time::Tick(local as i64),px_scale:1.0,seconds:local as f64/1000000.0,timecode:"",clip_name:"",project:None,env:None,working:filmcraft_color::WorkingSpace::Rec709};
   apply(&mut image,&effect,&cx);frames.push(image.px.iter().map(|v|v.to_bits()).collect::<Vec<_>>());
  }
  media.push(json!({"shape":if shape==0 {"linear"}else{"radial"},"localTick":tick,"rgba":rgba,"bits":frames[0],"frames":frames}));
 }
 }
 println!("{}",json!({"commit":"5231852443363f001c3f6b396dd9b1e6461ae2be","cases":cases,"media":media}));
}
